B.ah0=new A.b2("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.c5=new A.lT("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.a2s=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.aUb=new A.aa(B.c5,B.a2s,!1)
B.be=new A.lT("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.a5P=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.aW7=new A.aa(B.be,B.a5P,!1)
B.aa_=s([B.ah0,B.aUb,B.aW7],t.a)
B.aX7=new A.cy("story_00_intro",B.aa_)
B.agu=new A.b2("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.a39=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.aUj=new A.aa(B.c5,B.a39,!1)
B.ah7=new A.b2("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.a3i=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.aUf=new A.aa(B.be,B.a3i,!1)
B.cb=new A.lT("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.aaY=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.aVX=new A.aa(B.cb,B.aaY,!1)
B.a3u=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.aVo=new A.aa(B.c5,B.a3u,!1)
B.aa9=s([B.agu,B.aUj,B.ah7,B.aUf,B.aVX,B.aVo],t.a)
B.aWQ=new A.cy("story_01a_clubhouse_arrival",B.aa9)
B.a4z=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.aUO=new A.aa(B.c5,B.a4z,!1)
B.a69=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.aVs=new A.aa(B.cb,B.a69,!1)
B.a1x=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.aVK=new A.aa(B.be,B.a1x,!1)
B.a3e=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.aVH=new A.aa(B.cb,B.a3e,!1)
B.a2u=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.aV0=new A.aa(B.be,B.a2u,!1)
B.a0v=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.aTZ=new A.aa(B.c5,B.a0v,!1)
B.a8f=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.aWb=new A.aa(B.be,B.a8f,!1)
B.ac8=s([B.aUO,B.aVs,B.aVK,B.aVH,B.aV0,B.aTZ,B.aWb],t.a)
B.aWL=new A.cy("story_01b_legend_and_time",B.ac8)
B.ahy=new A.b2("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.a4D=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.aUV=new A.aa(B.be,B.a4D,!1)
B.a41=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.aWk=new A.aa(B.cb,B.a41,!1)
B.abD=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.aVG=new A.aa(B.be,B.abD,!1)
B.a7S=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.aTU=new A.aa(B.cb,B.a7S,!1)
B.a2g=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.aTX=new A.aa(B.c5,B.a2g,!1)
B.a6E=s([B.ahy,B.aUV,B.aWk,B.aVG,B.aTU,B.aTX],t.a)
B.aWK=new A.cy("story_02_torn_map",B.a6E)
B.a1y=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.aUU=new A.aa(B.c5,B.a1y,!1)
B.a8G=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.aW1=new A.aa(B.be,B.a8G,!1)
B.agO=new A.b2("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.ab1=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.aW2=new A.aa(B.cb,B.ab1,!1)
B.abg=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.aW5=new A.aa(B.be,B.abg,!1)
B.a7p=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.aUh=new A.aa(B.c5,B.a7p,!1)
B.a1U=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.aUM=new A.aa(B.be,B.a1U,!1)
B.a1Z=s([B.aUU,B.aW1,B.agO,B.aW2,B.aW5,B.aUh,B.aUM],t.a)
B.aWM=new A.cy("story_03_founders_trail",B.a1Z)
B.agw=new A.b2("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.a3G=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.aWf=new A.aa(B.be,B.a3G,!1)
B.a8a=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.aVB=new A.aa(B.cb,B.a8a,!1)
B.aaI=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.aVL=new A.aa(B.be,B.aaI,!1)
B.a4U=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.aVt=new A.aa(B.c5,B.a4U,!1)
B.a16=s([B.agw,B.aWf,B.aVB,B.aVL,B.aVt],t.a)
B.aWI=new A.cy("story_04_flowers_in_mud",B.a16)
B.agT=new A.b2("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.a2T=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.aUq=new A.aa(B.be,B.a2T,!1)
B.a0A=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.aVn=new A.aa(B.cb,B.a0A,!1)
B.a5p=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.aWo=new A.aa(B.be,B.a5p,!1)
B.ach=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.aUL=new A.aa(B.c5,B.ach,!1)
B.a7M=s([B.agT,B.aUq,B.aVn,B.aWo,B.aUL],t.a)
B.aXh=new A.cy("story_05_old_oak",B.a7M)
B.agP=new A.b2("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.a8L=s(["\u201eCo se to stalo?\u201c"],t.s)
B.aW6=new A.aa(B.be,B.a8L,!1)
B.a5f=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.aUJ=new A.aa(B.c5,B.a5f,!1)
B.a30=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.aUH=new A.aa(B.be,B.a30,!1)
B.a5R=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.aVw=new A.aa(B.c5,B.a5R,!1)
B.agB=new A.b2("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.a5s=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.aVk=new A.aa(B.cb,B.a5s,!1)
B.abZ=s([B.agP,B.aW6,B.aUJ,B.aUH,B.aVw,B.agB,B.aVk],t.a)
B.aWN=new A.cy("story_06_waterfall_chest",B.abZ)
B.ah6=new A.b2("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.a44=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.aWq=new A.aa(B.cb,B.a44,!1)
B.abV=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.aUK=new A.aa(B.c5,B.abV,!1)
B.ahp=new A.b2("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.ac6=s([B.ah6,B.aWq,B.aUK,B.ahp],t.a)
B.aX2=new A.cy("story_07_scroll",B.ac6)
B.agm=new A.b2("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.aax=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.aWg=new A.aa(B.be,B.aax,!1)
B.a9g=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.aTM=new A.aa(B.cb,B.a9g,!1)
B.a3b=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.aTR=new A.aa(B.be,B.a3b,!1)
B.a6q=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.aUr=new A.aa(B.cb,B.a6q,!1)
B.a7e=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.aW3=new A.aa(B.c5,B.a7e,!1)
B.a7N=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.aTJ=new A.aa(B.cb,B.a7N,!1)
B.a7I=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.aUt=new A.aa(B.be,B.a7I,!1)
B.a5q=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.aVa=new A.aa(B.cb,B.a5q,!1)
B.a2r=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.aUe=new A.aa(B.c5,B.a2r,!1)
B.a28=s([B.agm,B.aWg,B.aTM,B.aTR,B.aUr,B.aW3,B.aTJ,B.aUt,B.aVa,B.aUe],t.a)
B.aWT=new A.cy("story_08_ending_dialogue",B.a28)
